<script setup>
import { computed,nextTick,onBeforeUnmount,onMounted,reactive,ref } from 'vue'
import { api } from './api'
import ConditionEditor from './ConditionEditor.vue'
import QuestionEditor from './QuestionEditor.vue'
import VariableInsert from './VariableInsert.vue'
import MediaFlowEditor from './MediaFlowEditor.vue'
import CommerceFlowEditor from './CommerceFlowEditor.vue'
import LocationFlowEditor from './LocationFlowEditor.vue'
import RequestLocationEditor from './RequestLocationEditor.vue'
import UserInputFlowEditor from './UserInputFlowEditor.vue'
import DynamicListEditor from './DynamicListEditor.vue'

defineProps({currentUser:{type:Object,required:true}})
const flows=ref([]),selected=ref(null),graph=ref({nodes:[],edges:[]}),selectedNodeId=ref(null),selectedEdgeId=ref(null),canvas=ref(null),search=ref(''),error=ref(''),success=ref('')
const tags=ref([]),fields=ref([]),agents=ref([]),httpApis=ref([]),messageTextarea=ref(null),actionInput=ref(null)
const wire=reactive({active:false,sourceNodeId:null,sourceHandle:null,x:0,y:0,hoverNodeId:null,hoverHandle:null});const insertMenu=ref(null);const mediaTypes=new Set(['image','video','audio','file'])
const draft=reactive({title:'',text:'',media:'',caption:'',filename:'',latitude:'',longitude:'',location_name:'',address:'',location_button_text:'Share location',campaign_name:'',campaign_description:'',webhook_url:'',webhook_enabled:false,thank_you_text:'Thank you for your response!',trigger_type:'manual',trigger_value:'',capture_field_id:'',reply_type:'text',required:true,min_length:'',max_length:'',min_value:'',max_value:'',date_format:'%Y-%m-%d',pattern:'',validation_error:'',seconds:60,condition_field:'service_window',operator:'open',value:'',custom_field_key:'',compare_value:'',http_api_id:'',button_label:'',button_action:'next',action_value:'',row_generation:'static',dynamic_source_field_id:'',dynamic_array_path:'',dynamic_title_path:'',dynamic_description:'',dynamic_value_path:'',dynamic_save_field_id:'',dynamic_save_entire_object:false,product_name:'',product_description:'',product_price:'',product_currency:'ZAR',product_image:'',product_url:'',product_button_text:'View product',catalog_id:'',product_retailer_id:'',product_body:'',product_footer:''})
const definitions={trigger:{label:'Start Bot Flow',icon:'🤖',group:null,inputs:[],outputs:[['next','Compose Next Message']]},send_message:{label:'Text',icon:'💬',group:'Messages',inputs:[['input','Message']],outputs:[['next','Next']]},image:{label:'Image',icon:'🖼',group:'Messages',inputs:[['input','Message']],outputs:[['next','Next']]},video:{label:'Video',icon:'🎥',group:'Messages',inputs:[['input','Message']],outputs:[['next','Next']]},audio:{label:'Audio',icon:'🎵',group:'Messages',inputs:[['input','Message']],outputs:[['next','Next']]},file:{label:'File',icon:'📎',group:'Messages',inputs:[['input','Message']],outputs:[['next','Next']]},location:{label:'Send a Location',icon:'📍',group:'Messages',inputs:[['input','Message']],outputs:[['next','Next']]},request_location:{label:'Request Location',icon:'🧭',group:'Interactive',inputs:[['input','Action']],outputs:[['next','Next']]},user_input_flow:{label:'User Input Flow',icon:'📋',group:'Interactive',inputs:[['input','Action']],outputs:[['next','First Question']]},question:{label:'Question',icon:'❓',group:'Interactive',inputs:[['input','Reply']],outputs:[['next','Next Question'],['thank_you','Thank You']]},interactive:{label:'Interactive Message',icon:'🔘',group:'Interactive',inputs:[['input','Reply']],outputs:[['next','Next'],['buttons','Buttons'],['list_messages','List Messages'],['ecommerce','E-commerce']]},button:{label:'Button',icon:'↖',group:'Interactive',inputs:[['input','Reply']],outputs:[['next','Next'],['sequence','Subscribe to Sequence']]},commerce:{label:'Product / Commerce',icon:'🛍️',group:'Interactive',inputs:[['input','Product']],outputs:[['next','Next']]},template:{label:'Template Message',icon:'🧩',group:'Interactive',inputs:[['input','Message']],outputs:[['next','Next']]},add_tag:{label:'Add tag',icon:'🏷',group:'Contact',inputs:[['input','Action']],outputs:[['next','Next']]},remove_tag:{label:'Remove tag',icon:'✂',group:'Contact',inputs:[['input','Action']],outputs:[['next','Next']]},set_field:{label:'Set custom field',icon:'📝',group:'Contact',inputs:[['input','Action']],outputs:[['next','Next']]},assign_user:{label:'Assign agent',icon:'👤',group:'Contact',inputs:[['input','Action']],outputs:[['next','Next']]},condition:{label:'Condition',icon:'⑂',group:'Flow control',inputs:[['input','Reply']],outputs:[['yes','True'],['no','False']]},delay:{label:'Delay',icon:'⏱',group:'Flow control',inputs:[['input','Action']],outputs:[['next','Next']]},set_status:{label:'Conversation status',icon:'✓',group:'Flow control',inputs:[['input','Action']],outputs:[['next','Next']]},http_request:{label:'HTTP request',icon:'🌐',group:'Integrations',inputs:[['input','Action']],outputs:[['success','Success'],['error','Error']]}}
const groupOrder=['Messages','Interactive','Contact','Flow control','Integrations'];const groups=computed(()=>groupOrder.map(label=>({label,items:Object.entries(definitions).filter(([,d])=>d.group===label&&d.label.toLowerCase().includes(search.value.toLowerCase()))})).filter(g=>g.items.length));const selectedNode=computed(()=>graph.value.nodes.find(n=>n.id===selectedNodeId.value)||null),selectedEdge=computed(()=>graph.value.edges.find(e=>e.id===selectedEdgeId.value)||null);const def=n=>definitions[n?.node_type]||{label:n?.node_type||'Block',icon:'⚡',inputs:[['input','Input']],outputs:[['next','Next']]},nodeWidth=250
function nodeById(id){return graph.value.nodes.find(n=>n.id===id)}function portY(n,handle,kind){const p=kind==='out'?def(n).outputs:def(n).inputs,i=Math.max(0,p.findIndex(x=>x[0]===handle));return 82+i*25}function nodeHeight(n){return Math.max(125,98+Math.max(def(n).inputs.length,def(n).outputs.length)*25)}function curve(sx,sy,tx,ty){const dx=Math.max(70,Math.abs(tx-sx)*.45);return `M ${sx} ${sy} C ${sx+dx} ${sy}, ${tx-dx} ${ty}, ${tx} ${ty}`}function edgePath(e){const s=nodeById(e.source_node_id),t=nodeById(e.target_node_id);if(!s||!t)return'';return curve(s.position_x+nodeWidth,s.position_y+portY(s,e.source_handle,'out'),t.position_x,t.position_y+portY(t,e.target_handle||'input','in'))}const livePath=computed(()=>{if(!wire.active)return'';const s=nodeById(wire.sourceNodeId);if(!s)return'';return curve(s.position_x+nodeWidth,s.position_y+portY(s,wire.sourceHandle,'out'),wire.x,wire.y)})
function operatorLabel(value){return({open:'is open',closed:'is closed',equals:'is',not_equals:'is not',contains:'contains',not_contains:'does not contain',starts_with:'starts with',ends_with:'ends with',empty:'is empty',not_empty:'is not empty'})[value]||value}function conditionSummary(c){const field=c.field||'service_window',op=c.operator||'open';if(field==='service_window')return `24-hour window ${op==='closed'?'closed':'open'}`;if(field==='assigned_user'){const name=agents.value.find(a=>String(a.id)===String(c.value))?.name||c.value||'unassigned';return `Assigned agent ${operatorLabel(op)} ${name}`.trim()}if(field==='tag')return `Contact tag ${operatorLabel(op)} ${c.value||''}`.trim();if(field==='conversation_status')return `Status ${operatorLabel(op)} ${c.value||''}`.trim();if(field==='custom_field'){const key=c.field_key||c.key||c.value||'';const label=fields.value.find(f=>f.key===key)?.label||key||'Custom field';return `${label} ${operatorLabel(op)} ${c.compare_value??''}`.trim()}return `${field} ${operatorLabel(op)} ${c.value||''}`.trim()}function replyTypeLabel(type){return({text:'text',email:'email',phone:'phone',date:'date',number:'number',integer:'whole number',decimal:'number',image:'photo',audio:'audio',video:'video',document:'document',sticker:'sticker',media:'media'})[type]||type}function questionSummary(c){const message=c.text||'Configure question',type=replyTypeLabel(c.reply_type||'text');const field=fields.value.find(f=>String(f.id)===String(c.capture_field_id));return `${message} · expects ${type}${field?` → ${field.label||field.name||field.key}`:''}`}
function summary(n){const c=n.config||{};if(n.node_type==='trigger')return c.trigger_value||c.trigger_type||'Manual';if(n.node_type==='question')return questionSummary(c);if(n.node_type==='request_location')return c.text||'Ask subscriber to share current location';if(n.node_type==='user_input_flow')return c.campaign_name||'Configure input campaign';if(n.node_type==='interactive'&&c.row_generation==='dynamic'){const f=fields.value.find(x=>String(x.id)===String(c.dynamic_source_field_id));return `${c.text||'Dynamic list'} · ${f?.label||f?.key||'select JSON field'}`}if(['send_message','interactive'].includes(n.node_type))return c.text||'Configure message';if(n.node_type==='button'&&c.row_generation==='dynamic'){const f=fields.value.find(x=>String(x.id)===String(c.dynamic_source_field_id));return `Dynamic rows · ${f?.label||f?.key||'select JSON field'}`}if(n.node_type==='location')return c.location_name||((c.latitude||c.longitude)?`${c.latitude||'?'} , ${c.longitude||'?'}`:'Configure location');if(n.node_type==='commerce')return `${c.product_name||'Configure product'}${c.product_price?` · ${c.product_currency||''} ${c.product_price}`:''}`.trim();if(mediaTypes.has(n.node_type))return c.caption||c.media||c.media_url||c.file_id||'Configure media';if(n.node_type==='condition')return conditionSummary(c);if(n.node_type==='delay')return `${c.seconds||60}s`;if(n.node_type==='http_request'){const item=httpApis.value.find(a=>String(a.id)===String(c.http_api_id));return item?item.name:'Select saved API'}return n.title||def(n).label}
async function insertVariable(prop,token,elRef){const el=elRef?.value,value=String(draft[prop]||''),start=el?.selectionStart??value.length,end=el?.selectionEnd??start;draft[prop]=value.slice(0,start)+token+value.slice(end);await nextTick();if(el){const pos=start+token.length;el.focus();el.setSelectionRange(pos,pos)}}async function loadConditionData(){const results=await Promise.allSettled([api.contactTags(),api.contactFields(),api.agents(),api.httpApis()]);if(results[0].status==='fulfilled')tags.value=results[0].value;if(results[1].status==='fulfilled')fields.value=results[1].value;if(results[2].status==='fulfilled')agents.value=results[2].value;if(results[3].status==='fulfilled')httpApis.value=(results[3].value||[]).filter(a=>a.active)}async function loadFlows(){try{flows.value=await api.flows();if(!selected.value&&flows.value.length)await selectFlow(flows.value[0])}catch(e){error.value=e.message}}async function selectFlow(flow){selected.value=await api.flow(flow.id||flow);graph.value=await api.flowGraph(selected.value.id);clearSelection();if(!graph.value.nodes.length)await seedGraph()}async function seedGraph(){const trigger=await api.addFlowNode(selected.value.id,{node_type:'trigger',title:'Start Bot Flow',config:{trigger_type:selected.value.trigger_type,trigger_value:selected.value.trigger_value},position_x:80,position_y:100});graph.value.nodes.push(trigger)}
async function addNode(type,pos=null){if(!selected.value)return null;const count=graph.value.nodes.length,base=mediaTypes.has(type)?{media:'',caption:'',filename:''}:type==='location'?{latitude:'%latitude%',longitude:'%longitude%',location_name:'',address:''}:type==='request_location'?{text:'Please share your current location.',location_button_text:'Share location'}:type==='user_input_flow'?{campaign_name:'',campaign_description:'',webhook_url:'',webhook_enabled:false,thank_you_text:'Thank you for your response!'}:type==='interactive'?{text:'Choose an option',row_generation:'static'}:type==='commerce'?{product_name:'',product_description:'',product_price:'',product_currency:'ZAR',product_image:'',product_url:'',product_button_text:'View product',catalog_id:'',product_retailer_id:'',product_body:'',product_footer:''}:type==='delay'?{seconds:60}:type==='condition'?{field:'service_window',operator:'open',value:''}:type==='question'?{text:'',capture_field_id:null,reply_type:'text',required:true,date_format:'%Y-%m-%d'}:type==='http_request'?{http_api_id:null}:type==='button'?{label:'',action:'next',action_value:'',row_generation:'static'}:{};const n=await api.addFlowNode(selected.value.id,{node_type:type,title:def({node_type:type}).label,config:base,position_x:pos?.x??370+(count%3)*300,position_y:pos?.y??100+Math.floor(count/3)*190});graph.value.nodes.push(n);selectNode(n);return n}
function selectNode(n){selectedNodeId.value=n.id;selectedEdgeId.value=null;insertMenu.value=null;const c=n.config||{},customKey=c.field_key||c.key||(c.field==='custom_field'?c.value:'')||'';Object.assign(draft,{title:n.title||'',text:c.text||'',media:c.media||c.media_url||c.file_id||'',caption:c.caption||'',filename:c.filename||'',latitude:c.latitude||'',longitude:c.longitude||'',location_name:c.location_name||'',address:c.address||'',location_button_text:c.location_button_text||'Share location',campaign_name:c.campaign_name||'',campaign_description:c.campaign_description||'',webhook_url:c.webhook_url||'',webhook_enabled:!!c.webhook_enabled,thank_you_text:c.thank_you_text||'Thank you for your response!',trigger_type:c.trigger_type||selected.value?.trigger_type||'manual',trigger_value:c.trigger_value??selected.value?.trigger_value??'',capture_field_id:c.capture_field_id||c.save_reply_field_id||'',reply_type:c.reply_type||c.input_type||'text',required:c.required!==false,min_length:c.min_length??'',max_length:c.max_length??'',min_value:c.min_value??'',max_value:c.max_value??'',date_format:c.date_format||'%Y-%m-%d',pattern:c.pattern||'',validation_error:c.validation_error||'',seconds:c.seconds||60,condition_field:c.field||'service_window',operator:c.operator||'open',value:c.field==='custom_field'?'':(c.value||''),custom_field_key:customKey,compare_value:c.compare_value||'',http_api_id:c.http_api_id||'',button_label:c.label||'',button_action:c.action||'next',action_value:c.action_value||'',row_generation:c.row_generation||'static',dynamic_source_field_id:c.dynamic_source_field_id||'',dynamic_array_path:c.dynamic_array_path||'',dynamic_title_path:c.dynamic_title_path||'',dynamic_description:c.dynamic_description||'',dynamic_value_path:c.dynamic_value_path||'',dynamic_save_field_id:c.dynamic_save_field_id||'',dynamic_save_entire_object:!!c.dynamic_save_entire_object,product_name:c.product_name||'',product_description:c.product_description||'',product_price:c.product_price||'',product_currency:c.product_currency||'ZAR',product_image:c.product_image||'',product_url:c.product_url||'',product_button_text:c.product_button_text||'View product',catalog_id:c.catalog_id||'',product_retailer_id:c.product_retailer_id||'',product_body:c.product_body||'',product_footer:c.product_footer||''})}function optionalNumber(v){return v===''||v===null||v===undefined?null:Number(v)}
function dynamicConfig(c){return {...c,row_generation:draft.row_generation||'static',dynamic_source_field_id:draft.dynamic_source_field_id?Number(draft.dynamic_source_field_id):null,dynamic_array_path:draft.dynamic_array_path||'',dynamic_title_path:draft.dynamic_title_path||'',dynamic_description:draft.dynamic_description||'',dynamic_value_path:draft.dynamic_value_path||'',dynamic_save_field_id:draft.dynamic_save_field_id?Number(draft.dynamic_save_field_id):null,dynamic_save_entire_object:!!draft.dynamic_save_entire_object}}
async function saveNode(){const n=selectedNode.value;if(!n)return;let c={...(n.config||{})};if(n.node_type==='trigger'){const triggerType=draft.trigger_type||'manual',triggerValue=triggerType==='keyword'?draft.trigger_value.trim():null;c={...c,trigger_type:triggerType,trigger_value:triggerValue};selected.value=await api.updateFlow(selected.value.id,{trigger_type:triggerType,trigger_value:triggerValue})}if(['send_message','interactive','question'].includes(n.node_type))c.text=draft.text;if(n.node_type==='interactive')c=dynamicConfig(c);if(mediaTypes.has(n.node_type))c={...c,media:draft.media,caption:draft.caption,filename:n.node_type==='file'?draft.filename:''};if(n.node_type==='location')c={...c,latitude:draft.latitude,longitude:draft.longitude,location_name:draft.location_name,address:draft.address};if(n.node_type==='request_location')c={...c,text:draft.text,location_button_text:draft.location_button_text};if(n.node_type==='user_input_flow')c={...c,campaign_name:draft.campaign_name,campaign_description:draft.campaign_description,webhook_url:draft.webhook_url,webhook_enabled:!!draft.webhook_enabled,thank_you_text:draft.thank_you_text};if(n.node_type==='commerce')c={...c,product_name:draft.product_name,product_description:draft.product_description,product_price:draft.product_price,product_currency:draft.product_currency,product_image:draft.product_image,product_url:draft.product_url,product_button_text:draft.product_button_text,catalog_id:draft.catalog_id,product_retailer_id:draft.product_retailer_id,product_body:draft.product_body,product_footer:draft.product_footer};if(n.node_type==='question')c={...c,capture_field_id:draft.capture_field_id?Number(draft.capture_field_id):null,reply_type:draft.reply_type||'text',required:!!draft.required,min_length:optionalNumber(draft.min_length),max_length:optionalNumber(draft.max_length),min_value:optionalNumber(draft.min_value),max_value:optionalNumber(draft.max_value),date_format:draft.date_format||'%Y-%m-%d',pattern:draft.pattern||'',validation_error:draft.validation_error||''};if(n.node_type==='delay')c.seconds=Number(draft.seconds);if(n.node_type==='condition')c=draft.condition_field==='custom_field'?{...c,field:'custom_field',operator:draft.operator,field_key:draft.custom_field_key,compare_value:draft.compare_value,value:''}:{...c,field:draft.condition_field,operator:draft.operator,value:draft.value,field_key:null,compare_value:null};if(n.node_type==='http_request')c={...c,http_api_id:draft.http_api_id?Number(draft.http_api_id):null};if(n.node_type==='button')c=dynamicConfig({...c,label:draft.button_label,action:draft.button_action,action_value:draft.action_value});const u=await api.updateFlowNode(selected.value.id,n.id,{title:draft.title||null,config:c});graph.value.nodes[graph.value.nodes.findIndex(x=>x.id===n.id)]=u;success.value='Changes saved';setTimeout(()=>success.value='',1500)}
async function deleteNode(n){if(n.node_type==='trigger'||!confirm('Delete this block and its connections?'))return;await api.deleteFlowNode(selected.value.id,n.id);graph.value.nodes=graph.value.nodes.filter(x=>x.id!==n.id);graph.value.edges=graph.value.edges.filter(e=>e.source_node_id!==n.id&&e.target_node_id!==n.id);clearSelection()}async function dragEnd(ev,n){if(wire.active)return;const r=canvas.value.getBoundingClientRect();n.position_x=Math.max(20,Math.round(ev.clientX-r.left-30+canvas.value.scrollLeft));n.position_y=Math.max(20,Math.round(ev.clientY-r.top-20+canvas.value.scrollTop));await api.updateFlowNode(selected.value.id,n.id,{position_x:n.position_x,position_y:n.position_y})}function stagePoint(ev){const r=canvas.value.getBoundingClientRect();return{x:ev.clientX-r.left+canvas.value.scrollLeft,y:ev.clientY-r.top+canvas.value.scrollTop}}function startWire(ev,n,handle){ev.preventDefault();ev.stopPropagation();const p=stagePoint(ev);Object.assign(wire,{active:true,sourceNodeId:n.id,sourceHandle:handle,x:p.x,y:p.y});window.addEventListener('pointermove',moveWire);window.addEventListener('pointerup',cancelWire,{once:true})}function moveWire(ev){if(wire.active)Object.assign(wire,stagePoint(ev))}function hoverInput(n,handle,on){if(!wire.active||n.id===wire.sourceNodeId)return;if(on){wire.hoverNodeId=n.id;wire.hoverHandle=handle}else{wire.hoverNodeId=null;wire.hoverHandle=null}}async function finishWire(ev,n,handle){if(!wire.active||n.id===wire.sourceNodeId)return;ev.preventDefault();ev.stopPropagation();const src=wire.sourceNodeId,sh=wire.sourceHandle;cancelWire();const edge=await api.addFlowEdge(selected.value.id,{source_node_id:src,source_handle:sh,target_node_id:n.id,target_handle:handle});graph.value.edges.push(edge)}function cancelWire(){wire.active=false;wire.sourceNodeId=null;wire.sourceHandle=null;wire.hoverNodeId=null;wire.hoverHandle=null;window.removeEventListener('pointermove',moveWire)}function selectEdge(ev,e){ev.stopPropagation();selectedEdgeId.value=e.id;selectedNodeId.value=null}async function deleteEdge(e=selectedEdge.value){if(!e)return;await api.deleteFlowEdge(selected.value.id,e.id);graph.value.edges=graph.value.edges.filter(x=>x.id!==e.id);selectedEdgeId.value=null}function openInsert(e){const s=nodeById(e.source_node_id),t=nodeById(e.target_node_id);insertMenu.value={edge:e,x:(s.position_x+t.position_x)/2+nodeWidth/2,y:(s.position_y+t.position_y)/2}}async function insertBlock(type){const m=insertMenu.value;if(!m)return;const old=m.edge,n=await addNode(type,{x:m.x-nodeWidth/2,y:m.y-60});await api.deleteFlowEdge(selected.value.id,old.id);graph.value.edges=graph.value.edges.filter(e=>e.id!==old.id);graph.value.edges.push(await api.addFlowEdge(selected.value.id,{source_node_id:old.source_node_id,source_handle:old.source_handle,target_node_id:n.id,target_handle:def(n).inputs[0]?.[0]||'input'}),await api.addFlowEdge(selected.value.id,{source_node_id:n.id,source_handle:def(n).outputs[0]?.[0]||'next',target_node_id:old.target_node_id,target_handle:old.target_handle||'input'}));insertMenu.value=null}function clearSelection(){selectedNodeId.value=null;selectedEdgeId.value=null;insertMenu.value=null;cancelWire()}function keydown(e){if((e.key==='Delete'||e.key==='Backspace')&&selectedEdge.value&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)){e.preventDefault();deleteEdge()}if(e.key==='Escape')clearSelection()}onMounted(()=>{loadFlows();loadConditionData();window.addEventListener('keydown',keydown)});onBeforeUnmount(()=>{window.removeEventListener('keydown',keydown);cancelWire()})
</script>
<template><section class="vfb"><aside class="palette"><div class="palette-head"><b>Flow blocks</b><small>Drag wiring from an output dot to an input dot</small></div><input v-model="search" placeholder="Search blocks…"><section v-for="g in groups" :key="g.label"><h4>{{g.label}}</h4><button v-for="[type,d] in g.items" :key="type" @click="addNode(type)"><span>{{d.icon}}</span>{{d.label}}</button></section></aside><main class="main"><header class="toolbar"><select v-if="flows.length" :value="selected?.id||''" @change="selectFlow(Number($event.target.value))"><option v-for="f in flows" :key="f.id" :value="f.id">#{{f.id}} · {{f.name}}</option></select><div class="legend"><span>Drag ● output → ● input</span><span>Click a line to edit it</span></div></header><div v-if="selected" ref="canvas" class="stage" @click.self="clearSelection"><svg class="edges"><path v-for="e in graph.edges" :key="e.id" :d="edgePath(e)" :class="{selected:selectedEdgeId===e.id}" @click="selectEdge($event,e)"/><path v-if="wire.active" :d="livePath" class="live"/></svg><article v-for="n in graph.nodes" :key="n.id" class="node" :class="{selected:selectedNodeId===n.id}" :style="{left:n.position_x+'px',top:n.position_y+'px',minHeight:nodeHeight(n)+'px'}" draggable="true" @dragend="dragEnd($event,n)" @click.stop="selectNode(n)"><header><span>{{def(n).icon}}</span><strong>{{n.title||def(n).label}}</strong><button v-if="n.node_type!=='trigger'" @click.stop="deleteNode(n)">×</button></header><p>{{summary(n)}}</p><div v-for="([handle,label],i) in def(n).inputs" :key="'i'+handle" class="port input" :style="{top:(70+i*25)+'px'}"><button @pointerenter="hoverInput(n,handle,true)" @pointerleave="hoverInput(n,handle,false)" @pointerup="finishWire($event,n,handle)"></button><span>{{label}}</span></div><div v-for="([handle,label],i) in def(n).outputs" :key="'o'+handle" class="port output" :style="{top:(70+i*25)+'px'}"><span>{{label}}</span><button @pointerdown="startWire($event,n,handle)"></button></div></article><div v-if="selectedEdge" class="edge-tools"><b>Connection</b><button @click="openInsert(selectedEdge)">＋ Insert block</button><button @click="deleteEdge()">× Remove</button></div><div v-if="insertMenu" class="insert-menu" :style="{left:insertMenu.x+'px',top:insertMenu.y+'px'}"><b>Insert block</b><button v-for="[type,d] in Object.entries(definitions).filter(([,d])=>d.group)" :key="type" @click="insertBlock(type)">{{d.icon}} {{d.label}}</button></div></div></main><aside v-if="selectedNode" class="drawer"><div class="drawer-head"><span>{{def(selectedNode).icon}}</span><div><h2>{{def(selectedNode).label}}</h2><p>Configure this block</p></div></div><div class="drawer-body"><label>Title<input v-model="draft.title"></label><template v-if="selectedNode.node_type==='trigger'"><label>Trigger type<select v-model="draft.trigger_type"><option value="keyword">Keyword</option><option value="first_message">First message</option><option value="manual">Manual</option></select></label><label v-if="draft.trigger_type==='keyword'">Keyword<input v-model="draft.trigger_value"></label></template><label v-if="['send_message','interactive','question'].includes(selectedNode.node_type)">Message<textarea ref="messageTextarea" v-model="draft.text" rows="6"></textarea><VariableInsert :fields="fields" @insert="token=>insertVariable('text',token,messageTextarea)"/></label><DynamicListEditor v-if="selectedNode.node_type==='interactive'" :draft="draft" :fields="fields"/><MediaFlowEditor v-if="mediaTypes.has(selectedNode.node_type)" :draft="draft" :fields="fields" :media-type="selectedNode.node_type"/><LocationFlowEditor v-if="selectedNode.node_type==='location'" :draft="draft" :fields="fields"/><RequestLocationEditor v-if="selectedNode.node_type==='request_location'" :draft="draft" :fields="fields"/><UserInputFlowEditor v-if="selectedNode.node_type==='user_input_flow'" :draft="draft"/><CommerceFlowEditor v-if="selectedNode.node_type==='commerce'" :draft="draft" :fields="fields"/><QuestionEditor v-if="selectedNode.node_type==='question'" :draft="draft" :fields="fields"/><label v-if="selectedNode.node_type==='delay'">Delay seconds<input v-model.number="draft.seconds" type="number" min="1"></label><ConditionEditor v-if="selectedNode.node_type==='condition'" :draft="draft" :tags="tags" :fields="fields" :agents="agents"/><template v-if="selectedNode.node_type==='http_request'"><label>HTTP API<select v-model="draft.http_api_id"><option value="">— Select API —</option><option v-for="item in httpApis" :key="item.id" :value="item.id">{{item.name}} · {{item.method}}</option></select></label><p class="hint">Response mappings configured on the saved HTTP API are applied automatically before the Success path continues.</p></template><template v-if="selectedNode.node_type==='button'"><label>Button / static row label<input v-model="draft.button_label"></label><DynamicListEditor :draft="draft" :fields="fields"/><template v-if="draft.row_generation!=='dynamic'"><label>Action<select v-model="draft.button_action"><option value="next">Continue</option><option value="start_flow">Start flow</option><option value="send_message">Send message</option><option value="url">Open URL</option></select></label><label v-if="draft.button_action!=='next'">Action value<input ref="actionInput" v-model="draft.action_value"></label></template></template></div><footer><button @click="selectedNodeId=null">Close</button><button class="save" @click="saveNode">Save changes</button></footer></aside><p v-if="error" class="toast error">{{error}}</p><p v-if="success" class="toast">{{success}}</p></section></template>
<style scoped>.vfb{height:100vh;display:grid;grid-template-columns:250px 1fr;position:relative;background:#eef4f7;color:#17352a}.palette{background:#fff;border-right:1px solid #dce5e8;overflow:auto}.palette-head{padding:18px;border-bottom:1px solid #edf1f3}.palette-head b,.palette-head small{display:block}.palette>input{margin:14px;width:calc(100% - 28px);padding:10px}.palette section{padding:0 12px 13px}.palette section button{width:100%;display:flex;gap:9px;padding:10px;border:0;border-bottom:1px solid #edf2f3;background:#fff}.main{min-width:0;display:flex;flex-direction:column}.toolbar{height:68px;background:#fff;padding:0 18px;display:flex;align-items:center;justify-content:space-between}.stage{position:relative;flex:1;overflow:auto;min-height:720px;background-image:radial-gradient(#c9d6db 1px,transparent 1px);background-size:24px 24px}.edges{position:absolute;width:2400px;height:1600px;pointer-events:none}.edges path{fill:none;stroke:#718790;stroke-width:2.4;pointer-events:stroke}.node{position:absolute;width:250px;background:#fff;border:1px solid #dbe5e7;border-radius:12px;box-shadow:0 8px 22px #0001}.node.selected{outline:2px solid #20c875}.node header{display:flex;gap:8px;padding:11px 12px;border-bottom:1px solid #edf2f3}.node header strong{flex:1}.node header button{border:0;background:none}.node p{padding:12px;margin:0;color:#6c7f78;font-size:12px}.port{position:absolute;display:flex;gap:7px;font-size:9px}.port.input{left:-7px}.port.output{right:-7px}.port button{width:14px;height:14px;border-radius:50%;border:2px solid #fff;background:#607985;box-shadow:0 0 0 1px #607985}.port.output span{order:-1}.drawer{position:absolute;z-index:40;left:0;top:0;bottom:0;width:500px;background:#fff;box-shadow:12px 0 32px #0002;display:flex;flex-direction:column}.drawer-head{display:flex;gap:12px;padding:24px 30px;border-bottom:1px solid #edf1ef}.drawer-head h2,.drawer-head p{margin:0}.drawer-body{padding:24px 30px;overflow:auto;flex:1}.drawer label{display:flex;flex-direction:column;gap:6px;font-size:12px;font-weight:700;margin-bottom:14px}.drawer input,.drawer textarea,.drawer select{border:1px solid #d7e1dd;border-radius:8px;padding:10px}.drawer footer{padding:14px 20px;border-top:1px solid #e3eae6;display:flex;justify-content:space-between}.drawer footer button{padding:10px 16px}.drawer footer .save{background:#16ad63;color:#fff}.hint{font-size:11px;color:#6c7f78;background:#f3f8f6;padding:10px;border-radius:8px}.edge-tools{position:fixed;bottom:24px;left:50%;background:#fff;padding:8px;z-index:25}.insert-menu{position:absolute;z-index:30;background:#fff;padding:8px;box-shadow:0 10px 30px #0002}.insert-menu button{display:block;width:100%;padding:8px;border:0;background:#fff;text-align:left}.toast{position:fixed;right:22px;bottom:22px;background:#e2f8eb;padding:10px}.toast.error{background:#ffe8e8}@media(max-width:900px){.vfb{grid-template-columns:1fr}.palette{display:none}.drawer{width:100%}}</style>